1	export type Cell = [number, number];
2	
3	const SURVIVAL_NEIGHBOUR_COUNTS = [2, 3];
4	const BIRTH_NEIGHBOUR_COUNT = 3;
5	
6	const keyOf = ([x, y]: Cell): string => `${x},${y}`;
7	
8	const neighboursOf = ([x, y]: Cell): Cell[] =>
9	  [-1, 0, 1].flatMap((dx) =>
10	    [-1, 0, 1]
11	      .filter((dy) => dx !== 0 || dy !== 0)
12	      .map((dy): Cell => [x + dx, y + dy]),
13	  );
14	
15	type IsAlive = (cell: Cell) => boolean;
16	
17	const aliveIn = (liveCells: Cell[]): IsAlive => {
18	  const liveKeys = new Set(liveCells.map(keyOf));
19	  return (cell) => liveKeys.has(keyOf(cell));
20	};
21	
22	const countLiveNeighbours = (cell: Cell, isAlive: IsAlive): number =>
23	  neighboursOf(cell).filter(isAlive).length;
24	
25	const uniqueCells = (cells: Cell[]): Cell[] => [
26	  ...new Map(cells.map((cell) => [keyOf(cell), cell])).values(),
27	];
28	
29	const deadNeighboursOf = (liveCells: Cell[], isAlive: IsAlive): Cell[] =>
30	  uniqueCells(liveCells.flatMap(neighboursOf).filter((cell) => !isAlive(cell)));
31	
32	export function nextGeneration(liveCells: Cell[]): Cell[] {
33	  const isAlive = aliveIn(liveCells);
34	
35	  const survivors = liveCells.filter((cell) =>
36	    SURVIVAL_NEIGHBOUR_COUNTS.includes(countLiveNeighbours(cell, isAlive)),
37	  );
38	
39	  const births = deadNeighboursOf(liveCells, isAlive).filter(
40	    (cell) => countLiveNeighbours(cell, isAlive) === BIRTH_NEIGHBOUR_COUNT,
41	  );
42	
43	  return [...survivors, ...births];
44	}
